{
  "extends": "../tslint.json",
  "rules": {
    "directive-selector": [
      true,
      "attribute",
      "app",
      "camelCase"
    ],
    "component-selector": [
      true,
      "element",
      "app",
      "kebab-case"
    ]
  }
}

{
  "extends": "../tsconfig.json",
  "compilerOptions": {
    "outDir": "../out-tsc/spec",
    "types": [
      "jasmine",
      "node"
    ]
  },
  "files": [
    "test.ts",
    "polyfills.ts"
  ],
  "include": [
    "**/*.spec.ts",
    "**/*.d.ts"
  ]
}

{
  "extends": "../tsconfig.json",
  "compilerOptions": {
    "outDir": "../out-tsc/app",
    "module": "ES2022",
    "types": []
  },
  "exclude": [
    "test.ts",
    "**/*.spec.ts"
  ]
}

// This file is required by karma.conf.js and loads recursively all the .spec and framework files

import 'zone.js/testing';
import { getTestBed } from '@angular/core/testing';
import {
  BrowserDynamicTestingModule,
  platformBrowserDynamicTesting
} from '@angular/platform-browser-dynamic/testing';

declare const require: any;

// First, initialize the Angular testing environment.
getTestBed().initTestEnvironment(
  BrowserDynamicTestingModule,
  platformBrowserDynamicTesting()
);
// Then we find all the tests.
const context = require.context('./', true, /\.spec\.ts$/);
// And load the modules.
context.keys().map(context);

/* You can add global styles to this file, and also import other style files */
@import "~@angular/material/prebuilt-themes/indigo-pink.css";
@import "~angular2-multiselect-dropdown/themes/default.theme.css";
@import "~ng-pick-datetime-ex/assets/style/picker.min.css";
@import "ngx-toastr/toastr";
@import '~typeface-open-sans/index.css';
$fa-font-path: '~@fortawesome/fontawesome-free/webfonts';
@import "@fortawesome/fontawesome-free/scss/fontawesome.scss";
@import "@fortawesome/fontawesome-free/scss/solid.scss";
@import "@fortawesome/fontawesome-free/scss/brands.scss";

:root {
  --primary-color: rgba(1, 102, 152, 1);
  --secondary-color: hsla(20, 88%, 44%, 1);
  --background: rgba(255, 255, 255, 1);
  --on-background-alt: rgba(66, 66, 66, 0.7);
  --box-shadow: 0 5px 20px 1px rgba(0, 0, 0, 0.5);
  --success: hsla(154, 73%, 46%, 1);
  --errors: hsla(0, 100%, 67%, 1);
}

[data-theme="dark"] {
  --primary-color: rgb(150, 65, 255);
  --primary-variant: #6c63ff;
  --secondary-color: #03dac5;
  --on-primary: #000;
  --on-background: rgba(255, 255, 255, 0.9);
  --on-background-alt: rgba(255, 255, 255, 0.7);
  --background: #121212;
}

body {
  font-family: Arial, Sans-Serif !important;
  font-size: 1rem;
  -moz-user-select: text;
}

.app-content>mat-card {
  font-family: Arial, Sans-Serif !important;
}

label {
  font-family: Arial, Sans-Serif !important;
}

.mat-option-text {
  font-family: Arial, Sans-Serif !important;
}

.input-select {
  background-color: white !important;
  height: 30px !important;
}

.dropdown-list ul li {
  font-family: Arial, Sans-Serif !important;
  z-index: unset !important;
}

.form-control {
  font-family: Arial, Sans-Serif !important;
  margin-left: 8px;
}

label {
  margin-top: 4px;
  // margin-left: 6px;

}

.dropdown-list.tagToBody.animated.fadeIn {
  position: sticky;
}


.app-navs h4 {
  font-family: Arial, Sans-Serif !important;
}

.common-note {
  background-color: #d1ecf1;
  border: 2px solid #bee5eb;
  border-radius: 8px;
  padding: 12px;
  font-family: Arial, sans-serif !important;
  font-size: smaller;
  margin-bottom: 10px;
  color: #0c5460;
}

#toast-container>div {
  opacity: 1 !important;
}

button {
  color: rgba(255, 255, 255, 1);
  background-color: rgba(1, 102, 152, 1);
  border-color: rgba(1, 102, 152, 1);
}

.btn-align-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

.primary-color {
  color: var(--background) !important;
}

.primary-background {
  background: var(--background) !important;
}

.btn-primary {
  color: var(--background) !important;
  background-color: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

.btn-outline-primary {
  color: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

.click-event {
  cursor: pointer;
}

.btn-outline-primary:hover {
  color: var(--background) !important;
  background-color: var(--primary-color) !important;
  border-color: var(--primary-color) !important;
}

.btn-primary:hover {
  filter: opacity(70%) !important;
}

.refresh-icon mat-icon {
  color: #fff;
}

// Login Page
div.my-login-page {
  font-size: 14px;
}

.my-login-page .brand {
  width: 10px;
  height: 10px;
}

.my-login-page .brand img {
  width: 100%;
}

.my-login-page .card-wrapper {
  width: 400px;
}

.my-login-page .card {
  border-color: transparent;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.05);
}

.my-login-page .card.fat {
  padding: 10px;
}

.my-login-page .card .card-title {
  margin-bottom: 30px;
}

.my-login-page .form-control {
  border-width: 2.3px;
}

.my-login-page .form-group label {
  width: 100%;
}

.my-login-page .btn.btn-block {
  padding: 12px 10px;
}

.my-login-page .margin-top20 {
  margin-top: 20px;
}

.my-login-page .no-margin {
  margin: 0;
}

.my-login-page .footer {
  margin: 40px 0;
  color: #888;
  text-align: center;
}

// Mandatory Field Indicator
.mandatory-indication {
  color: red;
  font-size: 15px;
  top: 3px;
  float: left;
  left: -1px;
}

// Tab Menu Styles
.mat-list-base {
  display: contents !important;
}

.cust-mat .mat-list-item-content {
  padding: 0 10px !important;
}

.home-paginations {
  position: absolute;
  right: 60px;
  top: 6px;
}

span.page-numbers {
  float: left;
  margin-right: 6px;
  font-size: 18px;
  padding-top: 4px;
}

i.sales-page-n-icons.fa {
  background-color: #2859c8;
  color: #323C43;
  font-size: 17px;
  padding: 7.8px 11px;
  float: left;
  margin-right: 1px;
  cursor: pointer;
}

i.disable-sales-page-n-icons.fa {
  background-color: #eeeeee;
  color: #BBD;
  font-size: 17px;
  padding: 7.8px 11px;
  float: left;
  margin-right: 1px;
  cursor: pointer;
}

.plans-details-tabs .mat-tab-header,
.mat-tab-nav-bar {
  background-color: #EFEFEF;
}

.plans-details-tabs nav-bar {
  background-color: #4b566d;
}


// .plans-details-tabs .mat-tab-header-pagination-controls-enabled .mat-tab-header-pagination {
//     display: flex;
//     background-color: #EC7011;
// }

// .plans-details-tabs .mat-tab-header-pagination-disabled .mat-tab-header-pagination-chevron, .mat-tab-header-pagination-chevron {
//     border-color: #fff;
// }




.plans-details-tabs .mat-tab-label {
  opacity: 1;
  border-right: 1px solid #fafafa;
  font: normal normal 600 15px/20px Arial;
}

.plans-details-tabs .mat-tab-link {
  opacity: 1;
  border-right: 1px solid #fafafa;
}

.plans-details-tabs .mat-tab-label-active {
  background-color: #016698;
  color: #ffffff !important;
}

// .plans-details-tabs .mat-tab-header-pagination.mat-tab-header-pagination-disabled {
//     background-color: #ef9e7a;
