import { Injectable } from '@angular/core';
import { Router, CanActivate, ActivatedRouteSnapshot } from '@angular/router';
import { AuthGuard } from './auth-guard.service';
import { JwtHelperService } from '@auth0/angular-jwt';
@Injectable({
  providedIn: 'root'
})
export class RoleguardService implements CanActivate {
  userDetails: any;
  isRoleExists: boolean = false;
  jwtHelper = new JwtHelperService();
  isAuthenticate: any;
  constructor(public auth: AuthGuard, public router: Router) {
    this.userDetails = localStorage.bearerToken;
    this.isAuthenticate = this.jwtHelper.decodeToken(this.userDetails);
  }
  canActivate(route: ActivatedRouteSnapshot): boolean {
    // this will be passed from the route config
    // on the data property
    const expectedRole = route.data.expectedRole;

    const token = localStorage.bearerToken;

    // decode the token to get its payload
    const tokenPayload = this.jwtHelper.decodeToken(this.userDetails);
    expectedRole.forEach(role => {
      if (tokenPayload.roles === role) {
        this.isRoleExists = true;
      }
      if (!this.isRoleExists) {
        this.router.navigate(['/home/apps']);
        return false;
      }
    });
    return true;
  }
  getRoutesList() {
    var token = this.jwtHelper.decodeToken(this.userDetails);
    return JSON.parse(token.userPrivileges);
  }
}

import { UserService } from './../PmCore/services/UserService/UserService.service';
import { Injectable, Inject } from '@angular/core';
import { Router, CanActivate, ActivatedRouteSnapshot, RouterStateSnapshot } from '@angular/router';
import { JwtHelperService } from '@auth0/angular-jwt';
//import { RoleguardService } from './roleguard.service';

@Injectable({
  providedIn: 'root'
})
export class AuthGuard implements CanActivate {
  userDetails: any;
  jwtHelper = new JwtHelperService();
  isAuthenticate: any;
  isValid: boolean;
  constructor(
    private router: Router,
    private userService: UserService,
    @Inject('BASE_URL') private baseUrl: string
    //private roleGaurd: RoleguardService
  ) {
    this.userDetails = localStorage.bearerToken;
    this.isAuthenticate = this.jwtHelper.decodeToken(this.userDetails);
  }

  canActivate(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
    if (localStorage.bearerToken) {
      const token = localStorage.bearerToken;
      this.isValid = this.jwtHelper.isTokenExpired(token);
      if (!this.isValid) {
        return true;
      }
      else {
            // you can save redirect url so after authoring we can move them back to the page they requested
            this.userService.logout().pipe().subscribe(
              resp=>{
                window.location.href = 'auth/login';
                window.location.reload();
              }
            );
    //location.reload();
      }
    }
    else {
      this.userService.logout().pipe().subscribe(
      resp=>{
        window.location.href = 'auth/login';
        window.location.reload();
      }
    );

      return;
      //this.router.navigateByUrl('/auth/login');
    }

    return false;

  }
  canLoad(route: ActivatedRouteSnapshot, state: RouterStateSnapshot) {
    //var privList = this.roleGaurd.getRoutesList();
    //if (privList) {
    //  privList.forEach(x => {
    //    if (x.value == route.url)
    //      return true;
    //  });
    //}

    return true;
  }
  public isAuthenticated(): boolean {

    const token = localStorage.bearerToken;

    // Check whether the token is expired and return
    // true or false
    return !this.jwtHelper.isTokenExpired(token);
  }
}

