    canActivate: [AuthGuard],
    data: {
      expectedRole: ['Manager', 'User']
    },
    canLoad: [RoleguardService, AuthGuard]
  },
  {
    path: 'subscription-edit/:flowType/:subscriptionId', component: SubscriptionEditComponent,
    canActivate: [AuthGuard],
    data: {
      expectedRole: ['Manager', 'User']
    },
    canLoad: [RoleguardService, AuthGuard]
