                a.download = this.reportObj.ReportName + '_' + tenantName + '_' + this._utility.reportTime() + ".csv"; // Changed extension to CSV
                document.body.appendChild(a);
                a.click();
                document.body.removeChild(a);
            },
            error => {
                console.log(error);
            }
        );
}

