  cursor: pointer;
}

.cardtile:before {
  background-color: white;
  color: white;
  content: " ";
  display: block;
  border-radius: 50%;
  border: 1px solid grey;
  position: absolute;
  top: -5px;
  left: -5px;
  width: 25px;
  height: 25px;
  text-align: center;
  line-height: 28px;
  transition-duration: 0.4s;
  transform: scale(0);
}

:checked+cardtile {
  border-color: #ddd;
}

:checked+cardtile:before {
  content: "✓";
  background-color: grey;
  transform: scale(1);
}

.checkList {
  text-align: left;
  font: normal normal 600 16px/22px Arial;
