.rowStyle {
  white-space: nowrap;
}

.checkStyle {
  margin-top: -17px;
  text-align: center;
  margin-left: 4px;
}

.my-pagination ::ng-deep .ngx-pagination .current {
  background: #193A7E;
}

.colStyle {
  white-space: nowrap;
  background-color: #1A3A7F;
  color: white;
}

.rowStyle {
  white-space: nowrap;
}

a.disabled {
  pointer-events: none;
  cursor: default;
}

ul {
  list-style-type: none;
}

li {
  display: inline-block;
}

input[type="checkbox"][id^="cb"] {
  display: none;
}

label {
  border: 1px solid #fff;
  padding: 5px;
  display: block;
  position: relative;
  margin: 10px;
  cursor: pointer;
}

label:before {
  background-color: white;
  color: white;
  content: " ";
  display: block;
  border-radius: 50%;
  border: 1px solid grey;
  position: absolute;
  top: -5px;
  left: -5px;
  width: 25px;
  height: 25px;
  text-align: center;
  line-height: 28px;
  transition-duration: 0.4s;
  transform: scale(0);
}

label img {
  height: 100px;
  width: 100px;
  transition-duration: 0.2s;
  transform-origin: 50% 50%;
}

:checked+label {
  border-color: #ddd;
}

:checked+label:before {
  content: "✓";
  background-color: grey;
  transform: scale(1);
}

:checked+label img {
  transform: scale(0.9);
  box-shadow: 0 0 5px #333;
  z-index: -1;
}

