        this.model.location = this.location;
        this.model.pageNumber = 1;
        this.model.keyWord = temp == "" ? null : temp;
        this.getSearchResultsLookUpfilterByAlarm(this.model);
      }
    } else {
      if (
        (this.alarmList.filteredData.length > 0 ||
          this.alarmList.filteredData.length == 0) &&
