label {
  border: 1px solid #fff;
  padding: 5px;
  display: block;
  position: relative;
 // margin: 10px;
  cursor: pointer;
}

label:before {
  background-color: white;
  color: white;
  content: " ";
  display: block;
  border-radius: 50%;
  border: 1px solid grey;
  position: absolute;
  top: -5px;
  left: -5px;
  width: 25px;
  height: 25px;
  text-align: center;
  line-height: 28px;
  transition-duration: 0.4s;
  transform: scale(0);
}

label img {
  height: 100px;
  width: 100px;
  transition-duration: 0.2s;
  transform-origin: 50% 50%;
}

:checked+label {
  border-color: #ddd;
}

:checked+label:before {
  content: "✓";
  background-color: grey;
  transform: scale(1);
}

:checked+label img {
  transform: scale(0.9);
  box-shadow: 0 0 5px #333;
  z-index: -1;
}

.checkedWidthClass{
  flex: 0 0 5%;
}
.nameWidthClass{
  flex: 0 0 15%;
  display: flex;
  justify-content: flex-start;

}

.descrWidthClass{
  flex: 0 0 25%;
  display: flex;
  justify-content: flex-start;
}
.logsWidthClass{
  flex: 0 0 15%;
  display: flex;
  justify-content: flex-start;
}

::ng-deep .mat-expansion-panel .mat-expansion-panel-header.cdk-keyboard-focused:not([aria-disabled=true]),
.mat-expansion-panel .mat-expansion-panel-header.cdk-program-focused:not([aria-disabled=true]),
.mat-expansion-panel:not(.mat-expanded) .mat-expansion-panel-header:hover:not([aria-disabled=true]) {
  background: #c6c6c6;
}
mat-cell:first-of-type, mat-footer-cell:first-of-type, mat-header-cell:first-of-type {
  padding-left: 0px !important;
}
@media(min-width:960px) and (max-width:1024px) {}

@media(min-width:360px) and (max-width:640px) {
  .py-2 {
    padding-top: 3.5rem !important;
}
.filter{
  border-radius:0px;
  width:100%;
}
.body {
  padding: 0 2px 2px;
  overflow: scroll;
}
.mat-expansion-panel-body {
  padding: 0 2px 2px;
}

.card-body {
  flex: 1 1 auto;
  min-height: 1px;
  padding: 0rem;
}
.mat-header-cell {
  font: normal normal bold 11px/12px Arial;
}
.mat-cell {
  font-size: 9px;
  width: 100px;
  padding-left: 5px;
}
}

